		service = "Bob Smith", cover = 5000, expires = t + 86400, state = "offered", rideId = "ABCDEF", at = t } }
	-- one of this crew's own offers is past its 30 minutes with no answer: it lapses on the next tick
	d.W.db.drive = d.W.db.drive or {}
	d.W.db.drive.iou = { RIDE551a = { rider = string.lower(T.TESTCHAR), name = T.TESTCHAR, rideId = "ABCDEF",
		cover = 5000, issued = t - 2000, expires = t + 86400, state = "offered", by = "someone else" } }
	w:advance(2)
	local v = d.W.db.drive.iou.RIDE551a
	eq(v and v.state, "void", "the unanswered offer lapsed")
	ok(#d:findText("offers a raincheck", true, true) > 0, "the window redrew at once and shows the waiting raincheck card")
	T.clean(w)
end)

